import heapq
from typing import List

def heap_queue_largest(nums: List[int], n: int) -> List[int]:
    if n <= 0:
        return []
    if len(nums) == 0:
        return []
    if n >= len(nums):
        return sorted(nums, reverse=True)

    return heapq.nlargest(n, nums)

def differ_At_One_Bit_Pos(a, b):
    xor = a ^ b
    if xor == 0:
        return False
    return (xor & (xor - 1)) == 0

def find_Rotations(s):
    n = len(s)
    if n == 0:
        return 0
    if n == 1:
        return 1

    for k in range(1, n):
        rotated = s[-k:] + s[:-k]
        if rotated == s:
            return k
    return n

def remove_Occ(s, c):
    first = s.find(c)
    last = s.rfind(c)

    if first == -1 or last == -1:
        return s

    if first == last:
        return s[:first] + s[first+1:]

    return s[:first] + s[last+1:]

def find_Volume(base_length, height, length):
    if base_length <= 0 or height <= 0 or length <= 0:
        return 0.0
    area = 0.5 * base_length * height
    volume = area * length
    return volume

