def comb_sort(arr):
    if not arr:
        return arr

    n = len(arr)
    gap = n
    swapped = True

    shrink_factor = 1.3

    while gap > 1 or swapped:
        gap = int(gap / shrink_factor)
        if gap < 1:
            gap = 1
        swapped = False

        for i in range(0, n - gap, gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

def dif_Square(n):
    if n == 0:
        return True
    if n < 0:
        return True

    # Iterate over factors from 1 up to sqrt(n)
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            x, y = i, n // i
            # Check if x and y have the same parity
            if (x % 2) == (y % 2):
                return True
    return False

