solution:
def find_tuples(tuples_list, k):
    """
    Find tuples where all elements are divisible by k.

    Args:
        tuples_list (list): List of tuples to check.
        k (int): Divisor value.

    Returns:
        list: List of tuples where all elements are divisible by k.
    """
    if k == 0:
        raise ValueError("k cannot be zero")

    result = []
    for t in tuples_list:
        if len(t) == 0:
            # Empty tuple is considered valid as there are no elements to violate the condition
            result.append(t)
        else:
            all_divisible = True
            for num in t:
                if num % k != 0:
                    all_divisible = False
                    break
            if all_divisible:
                result.append(t)

    return result

