from functools import lru_cache

def eulerian_num(n, m):
    """
    Compute the Eulerian number a(n, m), which counts permutations of 1..n
    with exactly m ascents.

    Recurrence: a(n, m) = (n - m) * a(n-1, m-1) + (m + 1) * a(n-1, m)
    Base cases:
      a(0, 0) = 1
      a(n, m) = 0 if m < 0 or m >= n
    """
    if m < 0 or m >= n:
        return 0
    if n == 0 and m == 0:
        return 1

    @lru_cache(maxsize=None)
    def dp(i, j):
        if j < 0 or j >= i:
            return 0
        if i == 0 and j == 0:
            return 1
        return (i - j) * dp(i - 1, j - 1) + (j + 1) * dp(i - 1, j)

