solution:
def magic_square_test(matrix):
    # Check if matrix is empty or has zero size
    if not matrix or len(matrix) == 0:
        return False

    # Check if matrix is square
    if len(matrix) != len(matrix[0]):
        return False

    n = len(matrix)
    target_sum = sum(matrix[0])

    # Check each row sum
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check each column sum
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != target_sum:
            return False

    # Check main diagonal
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != target_sum:
        return False

    # Check secondary diagonal
    secondary_diag_sum = sum(matrix[i][n - 1 - i] for i in range(n))
    if secondary_diag_sum != target_sum:
        return False

    return True
